from pathlib import Path
from html import escape
import textwrap
OUT=Path(__file__).resolve().parents[1]/'assets/architecture'
OUT.mkdir(exist_ok=True)
TEAL='#7fe3ca';BLUE='#8abfff';GOLD='#f1ca80';PURPLE='#c5adff'
def start(title,sub):
 return [f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 680" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(sub)}</desc><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#102137"/><stop offset="1" stop-color="#0a1021"/></linearGradient><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="none" stroke="#7fe3ca" stroke-width="1.5"/></marker><pattern id="dots" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#85b2d1" opacity=".12"/></pattern></defs><rect width="960" height="680" rx="24" fill="url(#bg)"/><rect width="960" height="680" rx="24" fill="url(#dots)"/><circle cx="875" cy="40" r="150" fill="#227a75" opacity=".1"/><g font-family="system-ui, sans-serif"><text x="46" y="49" fill="#7fe3ca" font-size="13" letter-spacing="3">UNIX / INSIDE THE SYSTEM</text><text x="46" y="96" fill="#eff7ff" font-size="32" font-weight="700">{escape(title)}</text><text x="46" y="128" fill="#a8bcd2" font-size="17">{escape(sub)}</text>''']
def card(s,x,y,w,h,title,body='',color=TEAL):
 s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="16" fill="#15283e" stroke="{color}" stroke-opacity=".55"/><rect x="{x+18}" y="{y+20}" width="5" height="26" rx="2" fill="{color}"/><text x="{x+36}" y="{y+40}" fill="{color}" font-size="23" font-weight="650">{escape(title)}</text>')
 for i,line in enumerate(textwrap.wrap(body,max(12,int((w-45)/10)))):s.append(f'<text x="{x+22}" y="{y+72+i*24}" fill="#d5e2ee" font-size="18">{escape(line)}</text>')
def arrow(s,x1,y1,x2,y2):s.append(f'<path d="M{x1},{y1} L{x2},{y2}" fill="none" stroke="{TEAL}" stroke-width="2" marker-end="url(#arrow)"/>')
def note(s,text):s.append(f'<text x="46" y="649" fill="#9db4ca" font-size="15">{escape(text)}</text>')
def save(name,s):s.append('</g></svg>');(OUT/(name+'.svg')).write_text(''.join(s),encoding='utf-8')
s=start('The layers of a Unix system','A useful map — not a rule that every request takes the same path.')
for y,title,body,c in [(165,'YOU','Choose a task: read, write, run or connect.',GOLD),(267,'USER SPACE','Terminal • shell • applications • libraries',BLUE),(389,'KERNEL','Processes • memory • files • devices • network',TEAL),(511,'HARDWARE','CPU • RAM • storage • network interface',PURPLE)]:card(s,100,y,760,86,title,body,c)
for a,b in [(251,267),(353,389),(475,511)]:arrow(s,480,a,480,b)
note(s,'System calls cross the user/kernel boundary. Applications do not have to go through a shell.');save('layers',s)
s=start('One command, eight small steps','Follow cat notes.txt from your keyboard to the next prompt.')
labels=[('1  TYPE','The terminal receives your text.'),('2  INTERPRET','The shell reads command and arguments.'),('3  START','A process runs the cat program.'),('4  OPEN','The kernel checks the file request.'),('5  READ','Bytes come from cache or storage.'),('6  WRITE','Output goes to the terminal.'),('7  FINISH','Cat exits with a result code.'),('8  READY','The shell shows a new prompt.')]
for i,(t,b) in enumerate(labels):
 col=i%4;row=i//4;x=36+col*232;y=185+row*215;card(s,x,y,204,175,t,b,TEAL if row else BLUE)
 if col<3:arrow(s,x+204,y+88,x+228,y+88)
s.append('<text x="44" y="390" fill="#9db4ca" font-size="15">Continue with step 5 on the next row ↓</text>')
note(s,'Simplified external-command path. Built-ins and implementation details can differ.');save('journey',s)
s=start('Inside the kernel','Several jobs cooperate to keep programs running.')
card(s,310,175,340,100,'KERNEL','Protected system services',TEAL)
items=[(40,340,'CPU SCHEDULER','Choose runnable work.'),(350,340,'MEMORY','Map and protect pages.'),(660,340,'FILESYSTEMS','Resolve paths and files.'),(190,490,'DEVICE DRIVERS','Communicate with hardware.'),(500,490,'NETWORK STACK','Move data between sockets.')]
for x,y,t,b in items:arrow(s,480,275,x+135,y)
for x,y,t,b in items:card(s,x,y,270,110,t,b,BLUE if y==340 else PURPLE)
note(s,'Conceptual responsibilities; actual subsystem boundaries vary between kernels.');save('kernel',s)
s=start('A request across the boundary','Example: a program wants to read a file.')
card(s,60,185,360,130,'APPLICATION','Calls a library function to open or read a file.',BLUE)
card(s,540,185,360,130,'LIBRARY','Prepares a request when a kernel service is needed.',BLUE)
arrow(s,420,250,530,250)
s.append('<path d="M45 365 H915" stroke="#f1ca80" stroke-dasharray="9 8"/><text x="55" y="352" fill="#f1ca80" font-size="17">USER SPACE</text><text x="55" y="392" fill="#f1ca80" font-size="17">KERNEL SPACE</text>')
arrow(s,720,315,720,425);card(s,540,435,360,135,'KERNEL','Checks access, performs work and returns a result.',TEAL)
card(s,60,435,360,135,'RESULT OR ERROR','Return bytes or an error code to user space.',GOLD);arrow(s,530,500,430,500);arrow(s,240,435,240,325)
note(s,'A library call may use zero, one or several system calls. This is a simplified request path.');save('syscalls',s)
s=start('Processes: create, run, finish','The classic fork → exec → wait idea.')
card(s,50,200,340,130,'PARENT SHELL','PID 1200 — waits for a foreground command.',BLUE)
card(s,560,200,340,130,'CHILD PROCESS','fork creates a child with a new PID.',TEAL);arrow(s,390,265,550,265)
card(s,560,425,340,140,'PROGRAM: cat','exec replaces the child’s program. Its PID stays the same.',PURPLE);arrow(s,730,330,730,415)
card(s,50,425,340,140,'EXIT STATUS','The parent collects the child’s result and shows a prompt.',GOLD);arrow(s,550,495,400,495)
note(s,'PID values are fictional. Process creation can use mechanisms other than this classic model.');save('processes',s)
s=start('Memory is a managed workspace','Virtual addresses are not physical RAM locations.')
card(s,45,190,260,160,'PROCESS A','Code • stack • heap • mapped data',BLUE);card(s,45,400,260,160,'PROCESS B','Its own protected virtual address space',PURPLE)
card(s,375,285,230,160,'MAPPING','Page tables and hardware translate addresses.',TEAL);arrow(s,305,270,365,325);arrow(s,305,480,365,390)
card(s,675,190,240,160,'RAM','Active pages and useful file caches',GOLD);card(s,675,400,240,160,'STORAGE','Persistent files; swap if configured',BLUE);arrow(s,605,325,665,270);arrow(s,605,390,665,480)
note(s,'Virtual memory is more than swap. Sharing and caching are deliberate, controlled mechanisms.');save('memory',s)
s=start('One file tree, many possible disks','Paths begin at / — the root directory.')
card(s,355,170,250,90,'/','Root of the tree',TEAL)
for x,t,b in [(40,'/etc','System settings'),(270,'/home','User folders'),(500,'/var','Changing data'),(730,'/dev','Device entries')]:
 card(s,x,330,190,115,t,b,BLUE);arrow(s,480,260,x+95,320)
card(s,220,495,280,100,'/home/learner','A sample home folder',PURPLE);arrow(s,365,445,360,485)
card(s,580,495,330,100,'/mnt/data','Could mount another filesystem',GOLD)
note(s,'Typical Linux examples. Directories and mount arrangements vary across Unix systems.');save('filesystem',s)
s=start('Read permissions as three groups','Example: 640 → rw- r-- ---')
for x,t,b,c in [(45,'OWNER: 6','4 + 2 = read and write',TEAL),(350,'GROUP: 4','4 = read only',BLUE),(655,'OTHERS: 0','0 = no mode-bit access',PURPLE)]:card(s,x,205,260,145,t,b,c)
card(s,80,425,380,140,'ORDINARY FILE','r: read contents\nw: change contents\nx: execute',TEAL)
card(s,500,425,380,140,'DIRECTORY','r: list names; x: traverse.\nw + x: change entries.',GOLD)
note(s,'Owner/group/other is the basic model. ACLs, privilege and other security policies can add rules.');save('permissions',s)
s=start('Standard streams connect programs','0 = input   ·   1 = normal output   ·   2 = error output')
card(s,40,220,245,145,'PROGRAM A','Reads data and writes bytes to stdout (1).',BLUE)
card(s,355,220,250,145,'KERNEL PIPE','Buffered bytes connect the two processes.',TEAL)
card(s,675,220,245,145,'PROGRAM B','Reads those bytes from stdin (0).',PURPLE)
arrow(s,285,295,345,295);arrow(s,605,295,665,295)
card(s,90,470,340,105,'ERROR STREAM (2)','Separate unless redirected',GOLD);arrow(s,160,365,250,460)
card(s,555,470,340,105,'FINAL OUTPUT (1)','Terminal, file or another pipe',TEAL);arrow(s,800,365,730,460)
note(s,'The shell sets up the connections. A pipe carries bytes; it does not interpret rows or columns.');save('streams',s)
s=start('From application to network','A socket is the program’s communication endpoint.')
for i,(t,b,c) in enumerate([('APPLICATION','Creates a request',BLUE),('SOCKET','An endpoint for data',TEAL),('KERNEL STACK','Protocols and routes',PURPLE)]):card(s,45+i*305,200,260,140,t,b,c)
arrow(s,305,270,340,270);arrow(s,610,270,645,270)
for i,(t,b,c) in enumerate([('REMOTE SERVICE','Receives the request',BLUE),('NETWORK','Other devices and links',TEAL),('DRIVER + NIC','Network hardware',GOLD)]):card(s,45+i*305,445,260,140,t,b,c)
arrow(s,785,340,785,435);arrow(s,655,515,620,515);arrow(s,350,515,315,515)
note(s,'DNS lookup and application encryption add their own steps. Actual paths depend on the system.');save('network',s)
s=start('From power-on to a user session','A common Linux path — other Unix systems differ.')
items=[('1  FIRMWARE','Prepare the machine.'),('2  BOOTLOADER','Load the selected kernel.'),('3  KERNEL','Initialize core services.'),('4  EARLY USERSPACE','Prepare the root filesystem.'),('5  SYSTEM MANAGER','Start and supervise services.'),('6  LOGIN / SESSION','Start a shell or desktop.')]
for i,(t,b) in enumerate(items):
 x=45+(i%3)*305;y=200+(i//3)*230;card(s,x,y,260,150,t,b,BLUE if i<3 else TEAL)
 if i%3<2:arrow(s,x+260,y+75,x+295,y+75)
s.append('<text x="46" y="392" fill="#9db4ca" font-size="16">Continue with step 4 below ↓</text>')
note(s,'systemd is common on Linux, not universal Unix. macOS uses launchd; BSD systems differ.');save('boot',s)
print('Built',len(list(OUT.glob('*.svg'))),'architecture illustrations')
